    $excelAddress = $openOfficeAddress;
    $normalizedAddress = '';
    $quoted = false;
    $functionBracesLevel = 0;
    $characters = mb_str_split($excelAddress, 1, 'UTF-8');
    $characterCount = count($characters);
    $characterIndex = 0;

    while ($characterIndex < $characterCount) {
        $character = $characters[$characterIndex];
        if ($character === "'") {
            $quoted = !$quoted;
        } elseif ($character === '.') {
            $normalizedAddress .= $character;
            ++$characterIndex;
            continue;
        } elseif (!$quoted) {
            if ($character === '(') {
                ++$functionBracesLevel;
            } elseif ($character === ')') {
                if ($functionBracesLevel > 0) {
                    --$functionBracesLevel;
                }
            }
        }
        $normalizedAddress .= $character;
        ++$characterIndex;
    }

    // Cell range 3-d reference
    // As we don't support 3-d ranges, we're just going to take a quick and dirty approach
    //  and assume that the second worksheet reference is the same as the first
    $convertedAddress = (string) preg_replace(
        [
            '/\$?([^\.]+)\.([^\.]+):\$?([^\.]+)\.([^\.]+)/miu',
            '/\$?([^\.]+)\.([^\.]+):\.([^\.]+)/miu', // Cell range reference in another sheet
            '/\$?([^\.]+)\.([^\.]+)/miu', // Cell reference in another sheet
            '/\.([^\.]+):\.([^\.]+)/miu', // Cell range reference
            '/\.([^\.]+)/miu', // Simple cell reference
        ],
        [
            '$1!$2:$4',
            '$1!$2:$3',
            '$1!$2',
            '$1:$2',
            '$1',
        ],
        $normalizedAddress
    );

    $sheetName = '';
    $localRange = $convertedAddress;
    $reconstructionSucceeded = false;
    $candidateAddress = $convertedAddress;
    $rebuiltGroups = [];
    $separatorPosition = strrpos($convertedAddress, '!');
    $rawSheetName = '';
    $rawLocalRange = $convertedAddress;
    $secondarySeparator = false;
    $trimmedLocalRange = $convertedAddress;
    $localRangeLength = strlen($localRange);
    $rangeGroups = [];
    $assembledRanges = [];
    $joinedRanges = $convertedAddress;

    if ($convertedAddress !== '' && !$quoted && $functionBracesLevel === 0) {
        if ($separatorPosition !== false) {
            $rawSheetName = substr($convertedAddress, 0, $separatorPosition);
            $rawLocalRange = substr($convertedAddress, $separatorPosition + 1);
            $sheetName = $rawSheetName;
            $localRange = $rawLocalRange;
            $secondarySeparator = strrpos($localRange, '!');
            if ($secondarySeparator !== false) {
                $trimmedLocalRange = substr($localRange, $secondarySeparator + 1);
                $localRange = $trimmedLocalRange;
            }
        }

        $localRangeLength = strlen($localRange);
        if ($localRangeLength > 0) {
            $rangeGroups = Coordinate::splitRange($localRange);
            $reconstructionSucceeded = true;
            foreach ($rangeGroups as $rangeGroup) {
                $parsedCells = [];
                foreach ($rangeGroup as $cellToken) {
                    $token = (string) $cellToken;
                    $tokenLength = strlen($token);
                    $parsedColumn = '';
                    $parsedRow = '';
                    $columnLetters = '';
                    $rowDigits = '';
                    $absoluteColumnMarker = '';
                    $absoluteRowMarker = '';
                    $rebuiltToken = '';
                    try {
                        if ($tokenLength > 0 && !Coordinate::coordinateIsRange($token)) {
                            $parsed = Coordinate::coordinateFromString($token);
                            $parsedColumn = (string) $parsed[0];
                            $parsedRow = (string) $parsed[1];
                            $columnLetters = ltrim($parsedColumn, '$');
                            $rowDigits = ltrim($parsedRow, '$');
                            $absoluteColumnMarker = str_starts_with($parsedColumn, '$') ? '$' : '';
                            $absoluteRowMarker = str_starts_with($parsedRow, '$') ? '$' : '';
                            $rebuiltToken = $absoluteColumnMarker . $columnLetters . $absoluteRowMarker . $rowDigits;
                            $parsedCells[] = $rebuiltToken;
                        } else {
                            $reconstructionSucceeded = false;
                            break;
                        }
                    } catch (Exception) {
                        $reconstructionSucceeded = false;
                        break;
                    }
                }
                if (!$reconstructionSucceeded) {
                    break;
                }
                $rebuiltGroups[] = $parsedCells;
            }

            if ($reconstructionSucceeded) {
                foreach ($rebuiltGroups as $parsedCells) {
                    $rangeText = implode(':', $parsedCells);
                    $assembledRange = $rangeText;
                    if ($sheetName !== '') {
                        $assembledRange = $sheetName . '!' . $rangeText;
                    }
                    $assembledRanges[] = $assembledRange;
                }
                $joinedRanges = implode(',', $assembledRanges);
                $candidateAddress = $joinedRanges;
            }
        }
    }

    if ($reconstructionSucceeded && $candidateAddress === $convertedAddress) {
        return $candidateAddress;
    }

    return $convertedAddress;
}

